import type { CompanionReaction, GrowthStage } from "./types";

/** The three animated clips every growth stage gets (see docs/flow/README.md). */
export type ClipName = "idle" | "hello" | "celebrate";

export interface StageClips {
  /** Pixel size of the clip videos. */
  video: { width: number; height: number };
  /**
   * Where the resting-pose body sits inside the video, as fractions of the
   * video size. Used to line the video up exactly with the still PNG art.
   * Generated by scripts/companion-clips/process_clip.py.
   */
  body: { left: number; top: number; width: number; height: number };
  src: Record<ClipName, string>;
}

/**
 * Stages that have animated clips. Add a stage here once its clips are
 * processed; stages without clips keep using the still art with CSS motion.
 */
export const STAGE_CLIPS: Partial<Record<GrowthStage, StageClips>> = {
  child: {
    video: { width: 284, height: 576 },
    body: { left: 0.14588, top: 0.12292, width: 0.76110, height: 0.8625 },
    src: {
      idle: "/companion/ari-child-idle.webm",
      hello: "/companion/ari-child-hello.webm",
      celebrate: "/companion/ari-child-celebrate.webm",
    },
  },
};

/** Which clip plays for each temporary reaction. `null` = hold still. */
export const REACTION_CLIP: Record<CompanionReaction, ClipName | null> = {
  idle: "idle",
  quietDay: "idle",
  hello: "hello",
  taskDone: "hello",
  milestone: "celebrate",
  focus: null,
};

/** One-shot clips end and hand back to idle; idle loops. */
export const LOOPING_CLIPS: ReadonlySet<ClipName> = new Set(["idle"]);

/**
 * Transparent VP9 WebM plays in Chromium browsers and Firefox. Safari can
 * play WebM but drops the alpha channel (the character would sit on a box),
 * so Safari keeps the still art until HEVC-with-alpha clips are added.
 */
export function supportsAlphaWebm(): boolean {
  if (typeof window === "undefined" || typeof document === "undefined") return false;
  const userAgent = window.navigator.userAgent;
  const isSafari = /^((?!chrome|chromium|crios|fxios|android|edg).)*safari/i.test(userAgent);
  if (isSafari) return false;
  const probe = document.createElement("video");
  return probe.canPlayType('video/webm; codecs="vp09.00.10.08"') !== "" || probe.canPlayType('video/webm; codecs="vp9"') !== "";
}
